WITH customer_totals AS (SELECT customer_id, SORT_ARRAY(COLLECT_SET(country)) AS country_list, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values FROM sessions WHERE TO_DATE(started_at) >= '2025-04-01' GROUP BY customer_id) SELECT c.id, c.signup_date, c.name, ct.country_list, ct.country_values FROM customers c INNER JOIN customer_totals ct ON c.id = ct.customer_id;
